contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }
    function testFuzz_property(address newOperator, bool successBefore) public {
        vm.assume(newOperator != address(this));
        vm.assume(newOperator != address(0));

        // Record whether the new operator can call withdrawAndUnwrap before the change
        vm.prank(newOperator);
        try c.withdrawAndUnwrap(0, false, address(0)) { successBefore = true; } catch { successBefore = false; }

        // Owner changes operator
        vm.prank(address(this));
        c.setOperator(newOperator);

        // After setOperator, the new operator should be able to call onlyOperatorOrOwner-restricted function
        vm.prank(newOperator);
        try c.withdrawAndUnwrap(0, false, address(0)) {
            assertTrue(true == true); // will succeed for reference, but fail for buggy (operator not set correctly)
        } catch {
            assertTrue(false);
        }
    }
}

